from pathlib import Path
import base64, json
R=Path(__file__).resolve().parents[2]
OUT=R/"renders/temple_reseau_strict_plus_v2"
REF=R/"source/temple_reseau_strict_plus_v2/references/reference.png"
m=json.loads((OUT/"manifest.json").read_text())
def uri(p): return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
data={e["id"]:{**e, "images":{n:uri(OUT/e["id"]/(n+".png")) for n in e["layers"]}, "schema":uri(OUT/e["id"]/"schema.png"), "composition":uri(OUT/e["id"]/"composition.png")} for e in m["rooms"]}
ref_uri=uri(REF); planche_uri=uri(OUT/"PLANCHE.png")
h=f'''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Temple STRICT+ — sévérité maximale</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#0a0a14;color:#e0deff;font:16px system-ui}}header,main,footer{{max-width:1260px;margin:auto;padding:24px}}h1{{font-size:28px}}.tag{{font-size:12px;letter-spacing:2px;color:#a0a0ff}}.toolbar{{display:flex;gap:10px;flex-wrap:wrap}}select,button{{padding:12px;border:1px solid #6a6ab8;border-radius:6px;background:#1e1e3a;color:#eee}}.layout{{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:24px}}canvas{{display:block;width:100%;max-width:768px;image-rendering:pixelated;background:#121022}}aside{{background:#1e1e2e;padding:18px;border-radius:8px}}label{{display:block;margin:12px 0;font-size:14px}}a{{color:#aaaaff}}</style><header><div class="tag">TEMPLE STRICT+ / 8PX / MÊME ROCHE EXACTE</div><h1>STRICT+ — même DA, même roche, même perspective, 8px</h1><p><b>8px quilting</b> + <b>masque roche exact</b> + <b>0 invention</b>. Toutes les textures viennent de <b>IMG_5004 408×408</b> sans recoloration. Bordure rocheuse identique.</p></header><main><div class="toolbar"><select id="room"></select><button id="plan">Schéma</button><button id="reference">Référence</button></div><div class="layout"><section><canvas id="view" width="512" height="512"></canvas><p id="status"></p></section><aside><b>Calques 512</b><div id="layers"></div></aside></div><p><img src="{planche_uri}" style="width:100%;image-rendering:pixelated"></p></main><script>const DATA={json.dumps(data)},REF="{ref_uri}",c=document.getElementById("view"),ctx=c.getContext("2d"),select=document.getElementById("room");let entry,images={{}},visible={{}},schema=false,reference=false;function image(s){{let im=new Image();im.src=s;return im}}const ref=image(REF);for(const [id,e] of Object.entries(DATA)){{let o=document.createElement("option");o.value=id;o.textContent=e.title;select.append(o)}}select.value="salle_traversee";function setup(){{entry=DATA[select.value];images={{}};visible={{}};const r=document.getElementById("layers");r.innerHTML="";for(const n of entry.layers){{images[n]=image(entry.images[n]);visible[n]=true;let l=document.createElement("label"),ch=document.createElement("input");ch.type="checkbox";ch.checked=true;ch.onchange=()=>visible[n]=ch.checked;l.append(ch,document.createTextNode(n));r.append(l)}}images.schema=image(entry.schema);document.getElementById("status").textContent=entry.title}}select.onchange=setup;document.getElementById("plan").onclick=e=>{{schema=!schema;reference=false}};document.getElementById("reference").onclick=e=>{{reference=!reference}};function draw(im){{if(im.complete&&im.naturalWidth)ctx.drawImage(im,0,0)}}function render(){{const w=reference?408:512,h=reference?408:512;if(c.width!==w||c.height!==h){{c.width=w;c.height=h}}ctx.clearRect(0,0,c.width,c.height);if(reference)draw(ref);else if(schema)draw(images.schema);else for(const n of entry.layers)if(visible[n])draw(images[n]);requestAnimationFrame(render)}}setup();requestAnimationFrame(render);</script></html>'''
(R/"apercu_temple_reseau_strict_plus_v2.html").write_text(h, encoding="utf8")
print("gallery done")
